from PIL import Image
import numpy as np, heapq
from scipy import ndimage as ndi
im=np.asarray(Image.open('/app/target.png').convert('RGB'))
mask=im.max(2)<60
lab,n=ndi.label(mask,structure=np.ones((3,3),int))
# thin
sk=mask.copy();
while True:
 old=sk.copy();
 for phase in (0,1):
  p2=np.roll(sk,1,0); p3=np.roll(np.roll(sk,1,0),-1,1); p4=np.roll(sk,-1,1); p5=np.roll(np.roll(sk,-1,0),-1,1); p6=np.roll(sk,-1,0); p7=np.roll(np.roll(sk,-1,0),1,1); p8=np.roll(sk,1,1); p9=np.roll(np.roll(sk,1,0),1,1); ns=[p2,p3,p4,p5,p6,p7,p8,p9]; B=sum(ns); A=sum((~ns[k]&ns[(k+1)%8]) for k in range(8)); cond=((~(p2&p4&p6)&~(p4&p6&p8)) if phase==0 else (~(p2&p4&p8)&~(p2&p6&p8))); rem=sk&(B>=2)&(B<=6)&(A==1)&cond; sk[rem]=0
 if np.array_equal(old,sk): break
D=ndi.distance_transform_edt(mask)
# endpoints identified from previous run
ends={1:[(457,333),(530,408)],2:[(676,367),(775,453)],4:[(296,468),(263,600)],3:[(378,458),(630,511)]}
def path(i, s, e):
 # Dijkstra across skeleton coords using 8 neighbors, weight axial/diag
 y0,x0=s[1],s[0]; y1,x1=e[1],e[0]; dist={(y0,x0):0}; prev={}; heap=[(0,(y0,x0))]
 while heap:
  dd,(y,x)=heapq.heappop(heap)
  if (y,x)==(y1,x1): break
  if dd!=dist[(y,x)]: continue
  for dy in (-1,0,1):
   for dx in (-1,0,1):
    if dx==dy==0: continue
    yy,xx=y+dy,x+dx
    if not (0<=yy<1024 and 0<=xx<1024 and sk[yy,xx] and lab[yy,xx]==i): continue
    nd=dd+(2**.5 if dx and dy else 1)
    if nd<dist.get((yy,xx),1e9): dist[(yy,xx)]=nd;prev[(yy,xx)]=(y,x);heapq.heappush(heap,(nd,(yy,xx)))
 node=(y1,x1); out=[node]
 while node!=(y0,x0): node=prev[node];out.append(node)
 out=out[::-1]; return np.array([(x,y) for y,x in out],float),dist[(y1,x1)]
for i in (1,2,4,3):
 xy,l=path(i,*ends[i]);
 # gaussian smooth polyline; keep samples every 20px arc length
 sm=np.column_stack([ndi.gaussian_filter1d(xy[:,0],2),ndi.gaussian_filter1d(xy[:,1],2)])
 ds=np.r_[0,np.cumsum(np.linalg.norm(np.diff(sm,axis=0),axis=1))]
 ts=np.arange(0,ds[-1]+.1,20); samples=np.column_stack([np.interp(ts,ds,sm[:,0]),np.interp(ts,ds,sm[:,1])]);
 print('\ncomp',i,'geod',l,'smooth length',round(ds[-1],1),'n',len(xy))
 for x,y in samples:
  print(tuple(round(float(z),1) for z in (x,y,D[int(round(y)),int(round(x))],2*D[int(round(y)),int(round(x))]*.22186)))
